package net.spell_engine.internals;
import java.util.*;import net.minecraft.core.Holder;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.effect.MobEffect;import net.spell_engine.api.spell.Spell;import net.spell_engine.fx.*;import net.spell_engine.api.spell.fx.*;
/** Native attack remains unchanged; only successful Mutilate contact gets a victim-side accent. */
public final class RogueVisuals {
 public static boolean after(boolean success,LivingEntity caster,Entity target,Holder<Spell> spell,Spell.Impact impact){if(success&&!caster.level().isClientSide()&&spell.is(Identifier.parse("rogues:vanish"))&&impact.action.type==Spell.Impact.Action.Type.STATUS_EFFECT&&"rogues:stealth".equals(impact.action.status_effect.effect_id)){for(String id:List.of("minecraft:glowing","archers:hunters_mark","skill_tree_rpgs:sinful_mark")){var effect=net.minecraft.core.registries.BuiltInRegistries.MOB_EFFECT.get(Identifier.parse(id));effect.ifPresent(caster::removeEffect);}}return success;}
 public static void attack(Player p,Entity target,net.spell_engine.internals.delivery.melee.Melee.AttackContext context){float before=target instanceof LivingEntity l?l.getHealth()+l.getAbsorptionAmount():0;p.attack(target);if(!p.level().isClientSide()&&context.spellId().equals(Identifier.parse("rogues:mutilate"))&&target instanceof LivingEntity living&&living.getHealth()+living.getAbsorptionAmount()<before&&!ClassStatusVisuals.concealed(living)){var group=ParticleGroupBuilder.magic(SpellEngineParticles.magic_spark,ParticleGroup.Motion.BURST).color(0xCE7474FFL).scale(.3f).batch(b->b.shape(ParticleGroup.Shape.CIRCLE).count(8).speed(.06f,.14f));ParticleHelper.sendBatches(target,List.of(group));}}
}
